bool NoNumberIsSeven(
  const std::vector<int64_t>& numbers,
  int64_t count
) {
  for (int64_t i = 0; i < count; ++i) {
    int64_t number = numbers.at(i);
    switch (number) {
      case 7:
        return false;
    }
    int64_t mirrored = (
      numbers.at(static_cast<int64_t>(numbers.size() - (1)) - i)
    );
    switch (mirrored) {
      case 7:
        return false;
    }
    int64_t rotated = (
      numbers.at(verification::FloorMod(i + (1), static_cast<int64_t>(numbers.size())))
    );
    switch (rotated) {
      case 7:
        return false;
    }
  }
  return true;
}

